package com.xjtu.iron.idempotent.core;import com.xjtu.iron.idempotent.api.repository.IdempotencyFailureInfo;import com.xjtu.iron.idempotent.api.spi.IdempotencyFailureClassifier;import java.time.Instant;/** 保守默认：业务异常默认不可重试。 */public final class DefaultIdempotencyFailureClassifier implements IdempotencyFailureClassifier{public IdempotencyFailureInfo classify(Throwable error,Instant at){String code=error==null?"EXECUTION_FAILED":error.getClass().getSimpleName();String msg=error==null?"execution failed":error.getMessage();return new IdempotencyFailureInfo(code,msg,false,at);}}
